#include <iostream>
#include <vector>

int missingNumber(const std::vector<int>& nums) {
    int n = static_cast<int>(nums.size());
    int missing = n;
    for (int i = 0; i < n; i++) {
        missing ^= i ^ nums[i];
    }
    return missing;
}

int main() {
    int n;
    std::cin >> n;
    std::vector<int> nums(n);
    for (int i = 0; i < n; i++) {
        std::cin >> nums[i];
    }
    std::cout << missingNumber(nums) << "\n";
    return 0;
}

